/* Local Bootstrap-compatible hooks used by the server-rendered MVP. */
(function(){"use strict";document.querySelectorAll("[data-toggle='password']").forEach(function(button){button.addEventListener("click",function(){var input=document.getElementById(button.dataset.target);if(input){input.type=input.type==="password"?"text":"password";button.setAttribute("aria-pressed",input.type==="text");}});});})();
